ErrorInfo checkError(int errorCode) {
    ErrorInfo info;
    if (errorCode == 0) {
        info.code = 1; // Success
        strcpy(info.message, "Operation successful");
    } else {
        info.code = 0; // Error
        strcpy(info.message, "An error occurred");
    }
    return info;
}

